1	// Acceptance test for the change request:
2	//   "When I open a client show me the projects I am doing for them."
3	//
4	// Opening a client (client-open-<id> from the clients list) lands on that client's detail page
5	// (client-detail-page, at /clients/<id>). The detail page lists THE PROJECTS being done for THAT
6	// client — only that client's projects, each shown with its name. A client with no projects shows
7	// an empty state (client-projects-empty) instead of the table (client-projects-table).
8	//
9	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
10	// endpoint): `clients` honours { id, name, email } and `projects` honours { id, name, clientId }.
11	import { test, expect, type Page } from '@playwright/test';
12	import { resetAndSeed } from '../support/seed';
13	
14	const projectRows = (page: Page) => page.locator('[data-testid^="project-row-"]');
15	
16	// Locate the one project row carrying the given name, regardless of its server-assigned id.
17	const projectRowNamed = (page: Page, name: string) =>
18	  projectRows(page).filter({
19	    has: page.getByTestId('project-name').getByText(name, { exact: true }),
20	  });
21	
22	test.describe('Client projects', () => {
23	  test('opening a client from the list lands on its detail page', async ({ page }) => {
24	    await resetAndSeed({
25	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
26	      projects: [],
27	    });
28	
29	    await page.goto('/clients');
30	    await expect(page.getByTestId('client-row-1')).toBeVisible();
31	
32	    // Opening the client is a navigation, not a flag: following it lands on that client's own
33	    // detail page.
34	    const open = page.getByTestId('client-open-1');
35	    await expect(open).toBeVisible();
36	    await open.click();
37	
38	    await expect(page).toHaveURL(/\/clients\/1$/);
39	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
40	  });
41	
42	  test('the detail page lists the projects being done for that client', async ({ page }) => {
43	    await resetAndSeed({
44	      clients: [
45	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
46	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
47	      ],
48	      projects: [
49	        { id: 1, name: 'Website Redesign', clientId: 1 },
50	        { id: 2, name: 'Billing System', clientId: 1 },
51	        // A project for a DIFFERENT client must not show on this client's page.
52	        { id: 3, name: 'Mobile App', clientId: 2 },
53	      ],
54	    });
55	
56	    await page.goto('/clients/1');
57	
58	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
59	    await expect(page.getByTestId('client-projects-table')).toBeVisible();
60	    await expect(page.getByTestId('client-projects-empty')).toHaveCount(0);
61	
