1	import { useState } from 'react';
2	import { isValidEmail } from './email';
3	import { useContacts, useCreateContact, type Contact } from './contacts';
4	
5	// The contacts panel on a client's page: the client's contacts in a table, and a form to add one.
6	// Server data is read from the shared ['contacts'] key and filtered to this client (CLAUDE.md
7	// rule 5) — never copied into state. The form's useState holds only what the user is currently
8	// typing; on submit it POSTs {clientId, name, email, role} and invalidates the key, so the table
9	// refreshes itself.
10	export function ClientContacts({ clientId }: { clientId: number }) {
11	  const { data: contacts } = useContacts();
12	  const [name, setName] = useState('');
13	  const [email, setEmail] = useState('');
14	  const [role, setRole] = useState('');
15	  const [emailError, setEmailError] = useState(false);
16	  const create = useCreateContact();
17	
18	  const forClient: Contact[] = (contacts ?? []).filter((c) => c.clientId === clientId);
19	
20	  return (
21	    <section data-testid="client-contacts">
22	      <h2>Contacts</h2>
23	      <table data-testid="client-contacts-table">
24	        <thead>
25	          <tr>
26	            <th>Name</th>
27	            <th>Email</th>
28	            <th>Role</th>
29	          </tr>
30	        </thead>
31	        <tbody>
32	          {forClient.map((contact) => (
33	            <tr key={contact.id} data-testid={`contact-row-${contact.id}`}>
34	              <td data-testid="contact-name">{contact.name}</td>
35	              <td data-testid="contact-email">{contact.email}</td>
36	              <td data-testid="contact-role">{contact.role}</td>
37	            </tr>
38	          ))}
39	        </tbody>
40	      </table>
41	
42	      <form
43	        data-testid="contact-form"
44	        onSubmit={(event) => {
45	          event.preventDefault();
46	          if (!name.trim() || !role.trim()) {
47	            return;
48	          }
49	          if (!isValidEmail(email)) {
50	            setEmailError(true);
51	            return;
52	          }
53	          setEmailError(false);
54	          create.mutate(
55	            { clientId, name, email, role },
56	            {
57	              onSuccess: () => {
58	                setName('');
59	                setEmail('');
60	                setRole('');
61	              },
62	            },
63	          );
64	        }}
65	      >
66	        <input
67	          data-testid="contact-form-name"
68	          placeholder="Name"
69	          value={name}
70	          onChange={(event) => setName(event.target.value)}
71	        />
72	        <input
73	          data-testid="contact-form-email"
74	          placeholder="Email"
75	          value={email}
76	          onChange={(event) => {
77	            setEmail(event.target.value);
78	            if (emailError) {
79	              setEmailError(false);
80	            }
81	          }}
82	        />
83	        {emailError && (
84	          <span data-testid="contact-form-email-error" role="alert">
85	            Enter a valid email address.
86	          </span>
87	        )}
88	        <input
89	          data-testid="contact-form-role"
90	          placeholder="Role"
91	          value={role}
92	          onChange={(event) => setRole(event.target.value)}
93	        />
94	        <button data-testid="contact-form-submit" type="submit">
95	          Add contact
96	        </button>
97	      </form>
98	    </section>
99	  );
100	}
